using Microsoft.EntityFrameworkCore; using RobotMissionMS.Business.Features.Schedules.DTOs; using RobotMissionMS.DataAccess.Entities; using RobotMissionMS.DataAccess.Enums; using RobotMissionMS.DataAccess.Persistence;
namespace RobotMissionMS.Business.Features.Schedules.Services;
public sealed class ScheduleService(RobotMissionDbContext db):IScheduleService {
 public async Task<IReadOnlyList<ScheduleResponse>> ListAsync(string? floor,CancellationToken ct=default){var q=db.MissionSchedules.AsNoTracking().Include(x=>x.MissionType).Include(x=>x.Zone).Include(x=>x.MissionScheduleStops).ThenInclude(x=>x.Location).Where(x=>x.DeletedAt==null);if(floor!=null)q=q.Where(x=>x.Zone.Code==floor);return (await q.OrderBy(x=>x.Name).ToListAsync(ct)).Select(x=>Map(x)).ToList();}
 public async Task<ScheduleResponse?> CreateAsync(Guid user,string floor,ScheduleRequest r,CancellationToken ct=default){if(r.DaysOfWeek.Distinct().Count()!=r.DaysOfWeek.Count||r.DaysOfWeek.Any(x=>x<1||x>7)||!TimeOnly.TryParseExact(r.RunTime,"HH:mm",out var time))return null;var zone=await db.Zones.SingleOrDefaultAsync(x=>x.Code==floor&&x.IsActive,ct);var type=await db.MissionTypes.SingleOrDefaultAsync(x=>x.Code==r.MissionTypeCode&&x.IsActive&&x.Mode==MissionMode.Schedule,ct);if(zone==null||type==null||r.MissionTypeCode is not ("WASTE_COLLECTION" or "CORRIDOR_CLEANING"))return null;var loc=await db.Locations.Where(x=>r.Stops.Contains(x.Code)&&x.ZoneId==zone.Id&&x.IsActive).ToListAsync(ct);if(loc.Count!=r.Stops.Count||loc.Select(x=>x.Code).Distinct().Count()!=r.Stops.Count)return null;var s=new MissionSchedule{Id=Guid.NewGuid(),Name=r.Name.Trim(),MissionTypeId=type.Id,ZoneId=zone.Id,DaysOfWeek=r.DaysOfWeek,RunTime=time,IsActive=r.IsActive,CreatedByUserId=user,CreatedAt=DateTime.UtcNow};for(var i=0;i<r.Stops.Count;i++)s.MissionScheduleStops.Add(new MissionScheduleStop{Id=Guid.NewGuid(),ScheduleId=s.Id,Seq=i+1,LocationId=loc.Single(x=>x.Code==r.Stops[i]).Id});db.MissionSchedules.Add(s);await db.SaveChangesAsync(ct);return Map(s,type.Code,zone.Code,loc);}
 public async Task<ScheduleResponse?> UpdateAsync(Guid id,Guid user,string floor,ScheduleRequest r,CancellationToken ct=default){if(r.DaysOfWeek.Distinct().Count()!=r.DaysOfWeek.Count||r.DaysOfWeek.Any(x=>x<1||x>7)||!TimeOnly.TryParseExact(r.RunTime,"HH:mm",out var time))return null;await using var tx=await db.Database.BeginTransactionAsync(ct);var s=await db.MissionSchedules.Include(x=>x.Zone).Include(x=>x.MissionType).Include(x=>x.MissionScheduleStops).ThenInclude(x=>x.Location).SingleOrDefaultAsync(x=>x.Id==id&&x.Zone.Code==floor&&x.DeletedAt==null,ct);if(s==null)return null;var type=await db.MissionTypes.SingleOrDefaultAsync(x=>x.Code==r.MissionTypeCode&&x.IsActive&&x.Mode==MissionMode.Schedule,ct);var loc=await db.Locations.Where(x=>r.Stops.Contains(x.Code)&&x.ZoneId==s.ZoneId&&x.IsActive).ToListAsync(ct);if(type==null||r.MissionTypeCode is not ("WASTE_COLLECTION" or "CORRIDOR_CLEANING")||loc.Count!=r.Stops.Count||loc.Select(x=>x.Code).Distinct().Count()!=r.Stops.Count)return null;s.Name=r.Name.Trim();s.MissionTypeId=type.Id;s.RunTime=time;s.DaysOfWeek=r.DaysOfWeek;s.IsActive=r.IsActive;db.MissionScheduleStops.RemoveRange(s.MissionScheduleStops);for(var i=0;i<r.Stops.Count;i++)db.MissionScheduleStops.Add(new MissionScheduleStop{Id=Guid.NewGuid(),ScheduleId=id,Seq=i+1,LocationId=loc.Single(x=>x.Code==r.Stops[i]).Id});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Map(s,type.Code,s.Zone.Code,loc);}
 public async Task<bool?> SetStatusAsync(Guid id,string floor,bool active,CancellationToken ct=default){var s=await db.MissionSchedules.SingleOrDefaultAsync(x=>x.Id==id&&x.Zone.Code==floor&&x.DeletedAt==null,ct);if(s==null)return null;s.IsActive=active;await db.SaveChangesAsync(ct);return true;}
 public async Task<bool?> DeleteAsync(Guid id,string floor,CancellationToken ct=default){var s=await db.MissionSchedules.SingleOrDefaultAsync(x=>x.Id==id&&x.Zone.Code==floor&&x.DeletedAt==null,ct);if(s==null)return null;if(await db.MissionScheduleRuns.AnyAsync(x=>x.ScheduleId==id&&(x.Status==ScheduleRunStatus.WaitingForRobot||x.Status==ScheduleRunStatus.Late),ct))return false;s.DeletedAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);return true;}
 public async Task<ScheduleRunResponse?> RunAsync(Guid id,Guid user,string floor,string key,CancellationToken ct=default){var s=await db.MissionSchedules.Include(x=>x.Zone).Include(x=>x.MissionType).Include(x=>x.MissionScheduleStops).ThenInclude(x=>x.Location).SingleOrDefaultAsync(x=>x.Id==id&&x.DeletedAt==null&&x.Zone.Code==floor,ct);if(s==null||string.IsNullOrWhiteSpace(key))return null;var old=await db.MissionScheduleRuns.SingleOrDefaultAsync(x=>x.ScheduleId==id&&x.IsManual&&x.IdempotencyKey==key,ct);if(old!=null)return new(){RunId=old.Id,Status=old.Status.ToString().ToUpperInvariant(),Replayed=true};var snap=System.Text.Json.JsonSerializer.Serialize(new{missionTypeCode=s.MissionType.Code,floor=s.Zone.Code,stops=s.MissionScheduleStops.OrderBy(x=>x.Seq).Select(x=>new{x.Seq,x.Location.Code})});var run=new MissionScheduleRun{Id=Guid.NewGuid(),ScheduleId=id,ScheduledFor=DateTime.UtcNow,IsManual=true,IdempotencyKey=key,RequestedByUserId=user,Status=ScheduleRunStatus.WaitingForRobot,RouteSnapshot=snap,CreatedAt=DateTime.UtcNow};db.MissionScheduleRuns.Add(run);await db.SaveChangesAsync(ct);return new(){RunId=run.Id,Status="WAITING_FOR_ROBOT",Replayed=false};}
 static ScheduleResponse Map(MissionSchedule s,string? type=null,string? floor=null,IReadOnlyList<Location>? loc=null)=>new(){Id=s.Id,Name=s.Name,MissionTypeCode=type??s.MissionType.Code,Floor=floor??s.Zone.Code,DaysOfWeek=s.DaysOfWeek,RunTime=s.RunTime.ToString("HH:mm"),Stops=(loc??s.MissionScheduleStops.Select(x=>x.Location).ToList()).Select(x=>x.Code).ToList(),IsActive=s.IsActive,NextRunAt=null}; }
